import pandas as pd

def clean(df):
    df = df.copy()
    # Fix island label variants (typos/misspellings)
    island_map = {"Bisco": "Biscoe", "Dram": "Dream"}
    df["island"] = df["island"].replace(island_map)
    # Remove exact duplicate rows (same penguin counted twice; penguin_id is unique)
    df = df.drop_duplicates()
    return df

def answer(df):
    counts = df.groupby("island").size()
    counts = counts[counts.index.notna()]
    return counts.to_dict()
